import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import UndoToast from './UndoToast';

describe('UndoToast', () => {
  const cardName = 'Suspended Spell';
  let onUndo: Vi.Mock;
  let onDismiss: Vi.Mock;

  beforeEach(() => {
    onUndo = vi.fn();
    onDismiss = vi.fn();
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('onDismiss fires once after AUTO_DISMISS_MS (6000) and not before', async () => {
    render(<UndoToast cardName={cardName} instanceId="a1" onUndo={onUndo} onDismiss={onDismiss} />);

    expect(screen.getByText('Suspended Spell removed')).toBeInTheDocument();
    expect(onDismiss).not.toHaveBeenCalled();

    await vi.advanceTimersByTimeAsync(5999);
    expect(onDismiss).not.toHaveBeenCalled();

    await vi.advanceTimersByTimeAsync(1);
    await waitFor(() => expect(onDismiss).toHaveBeenCalledTimes(1));
  });

  it('a second removal with the same cardName but a different instanceId gets its own full timer', async () => {
    render(<UndoToast cardName={cardName} instanceId="first" onUndo={onUndo} onDismiss={onDismiss} />);

    await vi.advanceTimersByTimeAsync(5000);
    expect(onDismiss).not.toHaveBeenCalled();

    render(<UndoToast cardName={cardName} instanceId="second" onUndo={onUndo} onDismiss={onDismiss} />);

    expect(onDismiss).not.toHaveBeenCalled();

    await vi.advanceTimersByTimeAsync(1500);
    expect(onDismiss).not.toHaveBeenCalled();

    await vi.advanceTimersByTimeAsync(1501);
    await waitFor(() => expect(onDismiss).toHaveBeenCalledTimes(1));
  });

  it('the card name is shown in the toast text', () => {
    render(<UndoToast cardName={cardName} instanceId="a1" onUndo={onUndo} onDismiss={onDismiss} />);

    expect(screen.getByText('Suspended Spell removed')).toBeInTheDocument();
  });

  it('the Undo button calls onUndo', () => {
    render(<UndoToast cardName={cardName} instanceId="a1" onUndo={onUndo} onDismiss={onDismiss} />);

    fireEvent.click(screen.getByText('Undo'));
    expect(onUndo).toHaveBeenCalledTimes(1);
  });

  it('the dismiss button calls onDismiss', () => {
    render(<UndoToast cardName={cardName} instanceId="a1" onUndo={onUndo} onDismiss={onDismiss} />);

    fireEvent.click(screen.getByRole('button', { name: /Dismiss/i }));
    expect(onDismiss).toHaveBeenCalledTimes(1);
  });
});

